scwin.gvPgmList_onviewchange = function(info) {
    if (info.colIndex == 3) {
        var matchArr = dlApplCode.getMatchedJSON("intgCdId", info.newValue, true);
        dlSuperUser.setCellData(info.rowIndex, "trckNm", matchArr[0].intgCdDesc);
    }
};
scwin.trigger1_onclick = function(e) {
    textbox1.setValue(gvPgmList.getFixedColumnLastIndex(false));
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'textbox1').innerText == '2'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /**
     * 화면 로딩시 호출
     *
     * @type function
     * @class scwin
     * @date 2018. 09. 21.
     * @param
     * @author YeoSan Yoon
     * @return {Promise} promise : promise object
     * @example
     * scwin.onpageload();
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
